import re
R=[]
for l in external_context.split('\n'):
    m=re.match(r'id=(\S+) region=\S+ status=\S+ value=(-?\d+) tags=(\S*)',l)
    if m:R.append((m[1],int(m[2]),m[3]))
tags={t for r in R for t in r[2].split(',') if t}
mx=max(r[1] for r in R)
print(len(R),len(tags),min(r[0] for r in R if r[1]==mx),sum(r[1] for r in R if r[0].endswith('3')))

